@@ -0,0 +1,79 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const ANNEX = { "X-Larder-Site": "annex" };
+
+// Puts 3 kg of item 1 (onion) into the annex fridge through a received order.
+async function stockAnnex(handle) {
+  const order = (await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 1, qty: 3 }] } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send` });
+  const res = await handle({ method: "POST", path: `/orders/${order.id}/receive`, headers: ANNEX, body: { lots: [{ lot: "AX-1", expires: "2026-10-30", location: "annex-fridge" }] } });
+  assert.equal(res.status, 200);
+  return res.body.batches[0];
+}
+
+test("the seed has two sites", async () => {
+  const { store } = app();
+  assert.deepEqual(store.data.sites.map((s) => s.id), ["main", "annex"]);
+  assert.deepEqual(store.data.locations.find((l) => l.id === "annex-fridge"), { id: "annex-fridge", name: "Annex fridge", tempC: 4, site: "annex" });
+});
+
+test("an unknown site is a 400 with its own code", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "x-larder-site": "attic" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+  assert.match(res.body.error.message, /attic/);
+});
+
+test("stock, batches, value and alerts only see the request's site", async () => {
+  const { handle } = app();
+  const annexEmpty = (await handle({ path: "/items", headers: ANNEX })).body;
+  assert.equal(annexEmpty.length, 6);
+  assert.ok(annexEmpty.every((i) => i.onHand === 0));
+  const batch = await stockAnnex(handle);
+  assert.equal((await handle({ path: "/items/1", headers: ANNEX })).body.onHand, 3);
+  assert.equal((await handle({ path: "/items/1" })).body.onHand, 10);
+  assert.deepEqual((await handle({ path: "/batches", headers: ANNEX })).body.map((b) => b.id), [batch.id]);
+  assert.equal((await handle({ path: `/batches/${batch.id}` })).status, 404);
+  assert.equal((await handle({ path: "/batches/1", headers: ANNEX })).status, 404);
+  assert.equal((await handle({ path: "/reports/stock-value", headers: ANNEX })).body.totalCents, 3 * 180);
+  const alerts = (await handle({ path: "/alerts", headers: ANNEX })).body;
+  assert.deepEqual(alerts.expiring.map((b) => b.lot), ["AX-1"]);
+  assert.ok(!(await handle({ path: "/alerts" })).body.expiring.some((b) => b.lot === "AX-1"));
+});
+
+test("receiving into another site's location is refused", async () => {
+  const { handle } = app();
+  const order = (await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 1, qty: 3 }] } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send` });
+  const res = await handle({ method: "POST", path: `/orders/${order.id}/receive`, body: { lots: [{ lot: "x", expires: null, location: "annex-fridge" }] } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_location");
+});
+
+test("cooking and waste use the request's site only", async () => {
+  const { handle, store } = app();
+  const cook = await handle({ method: "POST", path: "/recipes/1/cook", headers: ANNEX, body: { portions: 1 } });
+  assert.equal(cook.status, 409);
+  const batch = await stockAnnex(handle);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers: ANNEX, body: { qty: 1 } })).status, 404);
+  assert.equal((await handle({ method: "POST", path: `/batches/${batch.id}/waste`, headers: ANNEX, body: { qty: 1 } })).status, 201);
+  assert.equal(store.data.batches.find((b) => b.id === 1).qty, 4);
+});
+
+test("stock-takes belong to their site", async () => {
+  const { handle } = app();
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "dry" } })).status, 400);
+  const take = (await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: ANNEX })).status, 404);
+  const annex = await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "annex-fridge" } });
+  assert.equal(annex.status, 201);
+});
+
+test("shared data looks the same from every site", async () => {
+  const { handle } = app();
+  for (const path of ["/suppliers", "/dishes", "/recipes/1/cost"])
+    assert.deepEqual((await handle({ path, headers: ANNEX })).body, (await handle({ path })).body);
+});
